<script setup lang="ts">
import { serviceCatalog } from '../services';
import ActivityServerLink from './ActivityServerLink.vue';
import UiInput from './UiInput.vue';
import UiSelect from './UiSelect.vue';
import RefreshButton from './RefreshButton.vue';
import RelativeDate from './RelativeDate.vue';
import { onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { call } from '../api';
import type { ActivityPage,MonitoringTarget } from '../types';
const emit=defineEmits<{monitoring:[target:MonitoringTarget]}>();
const view=ref<ActivityPage>(),category=ref(''),phase=ref(''),search=ref(''),error=ref(''),busy=ref(false);
const cursors=ref<(string|null)[]>([null]),index=ref(0);
const categories:Record<string,string>={ssh:'SSH',server:'Server',ai:'AI',mcp:'MCP',process:'Process',app:'App'};
const phases:Record<string,string>={started:'Started',completed:'Finished',failed:'Failed',cancelled:'Cancelled',interrupted:'Interrupted',info:'Event'};
const serviceLabels = Object.assign({}, ...Object.values(serviceCatalog).map(spec => spec.activityLabels));
const actions:Record<string,string>={...serviceLabels,console_command:"SSH command",start_console_chat:"Fleet AI chat message",add_service_instance:"Add service connection",remove_service_instance:"Remove service connection",rename_service_instance:"Rename service connection",script_cancelled_by_user:"Request cancelled by user",script_grant_revoked:"Run approval revoked",script_rollback_started:"Configuration rollback",script_rollback_result:"Rollback result",script_proposed:"AI action proposed",script_review_started:"Risk review started",script_review_completed:"Risk review completed",script_awaiting_approval:"Awaiting approval",script_execution_started:"Approved action started",script_result:"Action result",script_approved_once:"Action approved once",script_approved_session:"Run approval granted",script_denied:"Action denied",script_request:"AI action request",exec:"Shell command request",cat:"Read file",grep:"Search file contents",ls:"List directory",du:"Measure disk usage",awk:"Read fields from file",sed:"Read lines from file",action_approval_notification:"Action approval notification",set_vulnerability_hidden:'Change vulnerability visibility',resolve_incident:'Incident resolved manually',configure_monitoring:'Configure monitoring',configure_notifications:'Configure notifications',notification_permission:'Request notification permission',notification_test:'Notification test',notification_send:'Send notification',notification_overflow:'Notification queue overflow',notification_unavailable:'Notifications unavailable',notification_queue_error:'Notification queue error','logs.collect':'Log analysis','packages.collect':'Scan installed packages','packages.collect_apt':'Check APT updates','services.collect_for':'Collect service diagnostics','auth.claude_token':'Check Claude authentication',detect_agents:'CLI check',poll:'Server polling',startup:'App started',shutdown:'App closed',window_hidden:'Window hidden',storage_cleanup:'Clean up local storage',pick_inventory_file:'Select inventory',add_source:'Add servers',sync_source:'Sync inventory',monitoring_wake:'Resuming monitoring after sleep',refresh_source:'Refresh server list',delete_source:'Delete server list',save_settings:'Save settings',update_settings:'Update settings',poll_server:'Refresh server',diagnose:'Refresh logs',refresh_packages:'Scan installed packages',refresh_apt:'Check APT updates',refresh_advisories:'Refresh advisories',update_source:'Download advisories',update_cvss:'Refresh CVE severity scores',configure_service:'Configure service diagnostics',refresh_service:'Collect service diagnostics',start_investigation:'Server AI chat message',cancel_investigation:'Stop AI run',save_server_dependencies:'Update server dependencies',start_group_investigation:'Start incident group investigation',resume_auto:'Resume automatic investigations',dismiss_auto_job:'Skip automatic investigation',new_check:'Create check',save_check_version:'Save check version',test_check_version:'Test check',preview_check_version:'Preview check',activate_check:'Enable check',disable_check:'Disable check',discard_check_version:'Delete check version',delete_check:'Delete check',run_checks:'Run checks',create_check_with_agent:'Draft check with AI',open_server:'Open server window',launch:'Isolated runner',preflight:'Check AI isolation',rejected_tool:'MCP tool blocked'};
let generation=0,disposed=false,timer:ReturnType<typeof setInterval>|undefined,debounce:ReturnType<typeof setTimeout>|undefined;
async function load(){
 const current=++generation;busy.value=true;error.value='';
 try {const result=await call<ActivityPage>('activity_log',{query:{before:cursors.value[index.value],category:category.value||null,phase:phase.value||null,search:search.value.trim()||null}});if(!disposed&&current===generation)view.value=result;}
 catch(e){if(!disposed&&current===generation)error.value=String(e).replace(/^Error: /,'');}
 finally{if(!disposed&&current===generation)busy.value=false;}
}
function refresh(){cursors.value=[null];index.value=0;void load();}
function older(){if(!view.value?.next||busy.value)return;cursors.value=cursors.value.slice(0,index.value+1);cursors.value.push(view.value.next);index.value++;void load();}
function newer(){if(index.value===0||busy.value)return;index.value--;void load();}
watch([category,phase,search],()=>{generation++;busy.value=true;clearTimeout(debounce);debounce=setTimeout(refresh,250);});
function visible(){if(!document.hidden&&index.value===0&&!busy.value)void load();}
onMounted(()=>{void load();timer=setInterval(visible,10000);document.addEventListener('visibilitychange',visible);});
onBeforeUnmount(()=>{disposed=true;generation++;clearInterval(timer);clearTimeout(debounce);document.removeEventListener('visibilitychange',visible);});
</script>
<template>
<section class="journal" :aria-busy="busy">
 <div class="toolbar"><UiSelect v-model="category" aria-label="Action category"><option value="">All categories</option><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></UiSelect><UiSelect v-model="phase" aria-label="Action result"><option value="">All results</option><option v-for="(label,key) in phases" :key="key" :value="key">{{label}}</option></UiSelect><UiInput v-model="search" type="search" maxlength="100" aria-label="Search the activity log" placeholder="Server address or ID"/><RefreshButton :disabled="busy" @click="refresh">{{busy?'Refreshing…':'Refresh'}}</RefreshButton></div>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <p v-if="view?.storage.error" class="error" role="alert">{{view.storage.error}}. Check available disk space and file permissions, then restart Cyberbot.</p>
 <p v-if="view?.storage.dropped" class="notice" role="status">Events not recorded: {{view.storage.dropped}}.</p>
 <p v-if="view?.expired" class="notice" role="status">These events have been rotated out. Refresh to see the latest events.</p>
 <p v-if="view?.skipped" class="notice" role="status">Corrupted entries skipped: {{view.skipped}}.</p>
 <div v-if="view?.events.length" class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Server or context</th><th>Result</th><th class="duration">Duration</th></tr></thead><tbody><tr v-for="event in view.events" :key="event.id"><td class="at"><RelativeDate :at="event.at" unit="milliseconds"/></td><td :title="`ID: ${event.operationId}${event.runId?` · AI: ${event.runId}`:''}`"><span class="category">{{categories[event.category]??event.category}}</span><span class="action">{{actions[event.action]??event.action}}</span><small v-if="event.aiAction?.goal" class="action-meta">{{event.aiAction.goal}}</small><button v-if="event.monitoring" class="definition" :title="`Version ${event.monitoring.version}`" @click="emit('monitoring',{definitionId:event.monitoring.definitionId,serverId:event.monitoring.serverId,instanceId:event.monitoring.instanceId})">{{event.monitoring.definitionId}} · {{({schedule:'scheduled',manual:'manually',ai:'request',startup:'launch'} as Record<string,string>)[event.monitoring.trigger]??event.monitoring.trigger}}</button><small v-if="event.aiAction" class="action-meta" :title="`Request ${event.aiAction.requestId} · hash ${event.aiAction.artifactHash} · ${event.aiAction.rules} · ${event.aiAction.model}/${event.aiAction.effort}`">{{event.aiAction.model}}<template v-if="event.aiAction.tokens!=null"> · {{event.aiAction.tokens.toLocaleString('en-US')}} risk review tokens</template></small></td><td class="target"><ActivityServerLink :event="event" empty="—"/></td><td><span class="phase" :class="event.phase">{{phases[event.phase]??event.phase}}</span></td><td class="duration">{{event.durationMs==null?'—':event.durationMs<1000?`${event.durationMs} ms`:`${(event.durationMs/1000).toFixed(1)} s`}}</td></tr></tbody></table></div>
 <p v-else-if="!busy&&!error&&!view?.expired" class="empty">{{view?.next?'No matching events on this page. Try older events.':category||phase||search?'No events match these filters.':'No activity recorded yet.'}}</p>
 <footer v-if="view"><span>{{(view.storage.bytes/1048576).toFixed(1)}} / {{Math.round(view.storage.limitBytes/1048576)}} MiB · old records are automatically deleted</span><div class="pagination"><button type="button" :disabled="busy||index===0" @click="newer">Newer</button><span>{{index+1}}</span><button type="button" :disabled="busy||!view.next" @click="older">Older</button></div></footer>
</section>
</template>
<style scoped>
.action-meta{display:block;font-size:10px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere}
.definition{font-size:10px;color:var(--accent);background:transparent;border:0;padding:3px 0;text-decoration:underline;text-underline-offset:3px}.journal{padding-bottom:24px}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:18px}button{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:7px 9px;min-width:0}button{display:inline-flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:hover:not(:disabled){background:var(--hover)}.toolbar>button{margin-left:auto}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}th{font-size:11px;font-weight:500;color:var(--muted);padding:8px 10px;border-bottom:1px solid var(--line)}td{padding:10px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.5}.at{font-size:11px;color:var(--muted);white-space:nowrap;font-variant-numeric:tabular-nums}.category{display:block;font-size:10px;color:var(--muted);margin-bottom:2px}.action{display:block;overflow-wrap:anywhere}.target{max-width:35ch;overflow-wrap:anywhere;color:var(--muted)}.duration{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--muted);font-size:11px}.phase{font-size:11px;white-space:nowrap;color:var(--muted)}.phase.completed{color:var(--success)}.phase.failed{color:var(--danger)}.phase.cancelled,.phase.interrupted{color:var(--warning)}footer{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:18px;color:var(--muted);font-size:11px}.pagination{display:flex;align-items:center;gap:12px}.pagination button{font-size:12px}.empty{padding:36px 0;color:var(--muted);font-size:13px}.error,.notice{padding:12px;border-radius:7px;font-size:12px;line-height:1.6;overflow-wrap:anywhere}.error{color:var(--danger);background:var(--danger-bg)}.notice{color:var(--warning);background:var(--warning-bg)}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:700px){.toolbar .ui-input{flex:1;min-width:150px}.toolbar>button{margin-left:0}td,th{padding:8px 6px}.duration{display:none}.target{max-width:23ch}.at{white-space:normal}}
</style>
